/**
 * Text-translation language catalog (GPT Text Translation Language Catalog,
 * edition 2026-09-23; 343 entries across 10 regional groups).
 *
 * This describes practicality of *written* GPT text-to-text translation —
 * the Translate step in the workspace (`gpt-4.1-mini` by default). It does
 * NOT describe ElevenLabs voice/TTS language support, which is a much
 * smaller, separate list (see `elevenlabs-languages.ts`) — the source
 * document explicitly excludes transcription, speech recognition and
 * text-to-speech. Keep the two lists separate; do not use tiers here to
 * decide which ElevenLabs voices to show.
 */

export type TranslationTier = "STRONG" | "GOOD_PRACTICAL" | "EXPERIMENTAL_VERIFY";

export type TranslationLanguageEntry = {
  id: string;
  englishName: string;
  autonym: string;
  isoCode: string;
  regionGroup: string;
  primaryRegion: string;
  tier: TranslationTier;
};

export const TRANSLATION_TIER_LABEL: Record<TranslationTier, string> = {
  STRONG: "Strong",
  GOOD_PRACTICAL: "Good — practical",
  EXPERIMENTAL_VERIFY: "Experimental — verify"
};

/** What each tier means for product use, from the catalog's own "how to use" guidance. */
export const TRANSLATION_TIER_GUIDANCE: Record<TranslationTier, string> = {
  STRONG: "Suitable for broad use after normal QA — test scripts, common domains, names, numbers and both directions.",
  GOOD_PRACTICAL: "Enable after language-specific evaluation. Uncommon domains and dialects may need review; show a quality notice.",
  EXPERIMENTAL_VERIFY: "Treat as a pilot. Route through human review rather than publishing unverified translations."
};

