/** Case/diacritic-loose match by English name, autonym or ISO code. */
export function findTranslationLanguage(query: string): TranslationLanguageEntry | null {
  const needle = query.trim().toLowerCase();
  if (!needle) return null;
  return (
    TRANSLATION_LANGUAGE_CATALOG.find((entry) => entry.isoCode.toLowerCase() === needle) ??
    TRANSLATION_LANGUAGE_CATALOG.find((entry) => entry.englishName.toLowerCase() === needle || entry.autonym.toLowerCase() === needle) ??
    TRANSLATION_LANGUAGE_CATALOG.find((entry) => entry.englishName.toLowerCase().includes(needle)) ??
    null
  );
}
